// Extract lead data from query params (from Slack button)
const query = $input.first().json.query || {};

const lead = {
  email: query.email || '',
  name: query.name || '',
  company: query.company || '',
  title: query.title || '',
  company_domain: '',
  source: 'slack-button'
};

// Extract domain from email
if (lead.email) {
  const emailParts = lead.email.split('@');
  lead.company_domain = emailParts.length > 1 ? emailParts[1] : '';
}

// Skip free email domains
const freeEmailDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com', 'aol.com'];
if (freeEmailDomains.includes(lead.company_domain)) {
  lead.company_domain = ''; // Will rely on company name for enrichment
}

return { json: lead };

// Compile research data from Apollo
const lead = $('Extract Lead Data').item.json;
const personData = $('Apollo: Enrich Person').item.json || {};
const companyData = $('Apollo: Enrich Company').item.json || {};
const warmOpensData = $('Lookup Warm Opens Data').item.json || {};

const person = personData.person || {};
const company = companyData.organization || {};

// Extract behavior signals from warm opens
const openCount = parseInt(warmOpensData.open_count) || 0;
const lastOpen = warmOpensData.last_open || '';
const campaigns = warmOpensData.campaigns || '';
const bookedAt = warmOpensData.booked_at || '';
const bookingUrl = warmOpensData.booking_url || '';

return {
  json: {
    lead,
    person: {
      name: person.name || lead.name || `${person.first_name || ''} ${person.last_name || ''}`.trim(),
      title: person.title || lead.title || 'Unknown',
      linkedin: person.linkedin_url || null,
      email: person.email || lead.email,
      phone: person.phone_numbers?.[0]?.sanitized_number || null,
      photo_url: person.photo_url || null
    },
    company: {
      name: company.name || lead.company || 'Unknown Company',
      domain: company.primary_domain || lead.company_domain,
      description: company.short_description || company.seo_description || '',
      industry: company.industry || 'Unknown',
      employees: company.estimated_num_employees || 'Unknown',
      funding: company.total_funding_printed || 'Unknown',
      location: company.city ? `${company.city}, ${company.country}` : 'Unknown',
      logo: company.logo_url || null,
      tech: company.technologies || [],
      linkedin_url: company.linkedin_url || null,
      twitter_url: company.twitter_url || null,
      founded_year: company.founded_year || null,
      keywords: company.keywords || []
    },
    behavior: {
      openCount,
      lastOpen,
      campaigns,
      isHotLead: openCount >= 3 || (lastOpen && new Date(lastOpen) > new Date(Date.now() - 24*60*60*1000))
    },
    booking: {
      hasBooking: Boolean(bookedAt),
      bookedAt,
      bookingUrl
    }
  }
};

